// Estrutura correta do input - objeto único com payloads e contexto
const inputData = $input.first().json

const contexto = inputData.contexto || {}
const templates = $('Templates')?.first()?.json || {}
const currentTaskId = contexto.id_tarefa_atual ?? null
const payloadSessao = inputData.payloadSessao || {}
const payloadTarefas = inputData.payloadTarefas || {}

// Verificação segura para currentTaskData
let currentTaskData = null
try {
  const workflowData = $('Inicia pelo workflow dos dados de documentos')?.first()?.json
  if (workflowData && workflowData.dados_documentos_fiscais) {
    // Busca dinamicamente qual objeto de "dados_documentos_fiscais" contém o array de "tarefas"
    const objTarefas = workflowData.dados_documentos_fiscais.find(item => item.tarefas)

    if (objTarefas && objTarefas.tarefas) {
      // Se tem currentTaskId (ope001_codigo), pega a tarefa correspondente
      if (currentTaskId) {
        currentTaskData = objTarefas.tarefas.find(tarefa => String(tarefa.ope001_codigo) === String(currentTaskId))
      } else {
        currentTaskData = objTarefas.tarefas[0] // Pega a primeira tarefa
      }
    }
  }
} catch (error) {
  console.log("Erro ao buscar currentTaskData:", error.message)
}


// ==========================================
// CONSTRUTORES DE MENSAGENS Z-API
// ==========================================

class WhatsAppMessageFactory {
  constructor(to) {
    this.to = to
  }

  createListMessage(inputData) {
    return {
      phone: this.to,
      message: "Selecione do menu abaixo",
      optionList: {
        title: inputData?.header || "Opções disponíveis",
        buttonLabel: "Opções",
        options: (inputData?.options || []).map(option => ({
          id: option?.id?.toString() || "",
          title: option?.title || "",
          ...(option?.description && { description: option.description })
        }))
      }
    }
  }

  createButtonMessage(inputData) {
    return {
      phone: this.to,
      message: inputData?.header || "Selecione das opções abaixo",
      buttonList: {
        buttons: (inputData?.options || []).map(option => ({
          id: option?.id?.toString() || "",
          label: option?.title || "" // Z-API utiliza 'label' no lugar de 'title' para botões
        }))
      }
    }
  }

  createTextMessage(inputData) {
    return {
      phone: this.to,
      message: inputData?.content || ""
    }
  }

  createMessage(inputData) {
    if (!inputData || !inputData.type) {
      throw new Error(`Template inválido ou sem tipo: ${JSON.stringify(inputData)}`)
    }

    const messageTypes = {
      list: this.createListMessage,
      button: this.createButtonMessage,
      text: this.createTextMessage
    }

    const createFunction = messageTypes[inputData.type]
    if (!createFunction) {
      throw new Error(`Tipo de mensagem não suportado: ${inputData.type}`)
    }

    return createFunction.call(this, inputData)
  }
}

// ==========================================
// MENSAGENS DO GOOGLE MAPS
// ==========================================

// Função para construir mensagens com rota do Google Maps usando texto ou coordenadas
const createGMapsMessage = (lat, long, enderecoTexto, toNumber, cTe) => {
  let linkBusca;
  let descricaoRota;

  // Se tem latitude e longitude, usa rota exata. Se não, faz a busca pelo texto do endereço
  if (lat !== null && long !== null && lat !== undefined && long !== undefined) {
    // Usando padrão URL para buscar direto as coordenadas
    linkBusca = `https://maps.google.com/?q=${lat},${long}`;
    descricaoRota = "Clique abaixo para abrir a localização exata no Google Maps.";
  } else {
    // Monta a busca por texto encodada para URL (ex: RUA+FERNANDES+LIMA,+38+-+CENTRO)
    linkBusca = `https://maps.google.com/?q=${encodeURIComponent(enderecoTexto)}`;
    descricaoRota = "Coordenadas ausentes. Clique para buscar o endereço aproximado no Maps.";
  }

  return {
    phone: toNumber,
    message: `Status da tarefa de CTe ${cTe} alterado para: "Em andamento"`,
    linkUrl: linkBusca,
    title: "Abrir no Google Maps",
    linkDescription: descricaoRota
  }
}

// Função específica para o estado GMAPSLINK (Encerrado/Andamento)
const createGMAPSLINKMessage = (toNumber, currentTaskData, cTeAtual) => {
  if (currentTaskData) {
    // Monta o endereço em texto caso falte a latitude/longitude
    const enderecoCompleto = `${currentTaskData.endereco_logradouro || ''}, ${currentTaskData.endereco_numero || ''} - ${currentTaskData.endereco_bairro || ''}, ${currentTaskData.endereco_municipio || ''}`;

    const gmapsMessage = createGMapsMessage(
      currentTaskData.latitude,
      currentTaskData.longitude,
      enderecoCompleto,
      toNumber,
      cTeAtual 
    )
    return [gmapsMessage]
  } else {
    console.log("DEBUG - Não foi possível criar mensagem de Maps: dados da tarefa vazios")
    return []
  }
}

// ==========================================
// CONSTRUÇÃO BASEADA NO CONTEXTO
// ==========================================

// Função específica para o contexto completo
const createMessageFromContext = (templates, contexto, currentTaskData) => {
  // Cria o objeto "fábrica de mensagens"  
  const factory = new WhatsAppMessageFactory(contexto.id_whatsapp)
  const messages = []

  if (contexto.proximo_estado && contexto.proximo_estado.includes('CONFIRMAR_CTE')) {
    // Monta o endereço completo concatenando as informações separadas
    const enderecoCompleto = currentTaskData 
      ? `${currentTaskData.endereco_logradouro || ''}, ${currentTaskData.endereco_numero || ''} - ${currentTaskData.endereco_bairro || ''}, ${currentTaskData.endereco_municipio || ''}`
      : "Endereço não informado";

    const templateExpositor = {
      type: "text",
      content: `*TAREFA ESCOLHIDA:*

Endereço: ${enderecoCompleto}
CTe: ${currentTaskData?.cte001_codigo || "N/A"}
Remetente: ${currentTaskData?.remetente || "N/A"}
Destinatário: ${currentTaskData?.destinatario || "N/A"}`
    }
    const expositorTarefa = factory.createMessage(templateExpositor)
    messages.push(expositorTarefa)
  }

  // Se for GMAPSLINK, cria mensagem do Google Maps diretamente e aciona a função de fallback de endereço
  if (contexto.proximo_estado === "GMAPSLINK") {
    return createGMAPSLINKMessage(contexto.id_whatsapp, currentTaskData, contexto.cte_tarefa_atual)
  }

  const template = templates[contexto.proximo_estado]
  // Lança erro caso não exista template com o nome do proximo estado
  if (!template) {
    throw new Error(`Template não encontrado para o estado: ${contexto.proximo_estado}`)
  }

  // Para outros estados, usa a sequência normal
  const currentMessage = factory.createMessage(template)
  messages.push(currentMessage)

  // Trecho de simulação da torre
  if (contexto.confirmacao_torre === "1" && contexto.proximo_estado) {
    const mensagemConfirmacao = factory.createMessage(templates[(contexto.proximo_estado).replaceAll("AGUARDAR", "CONFIRMAR")])
    messages.push(mensagemConfirmacao)
  }

  return messages
}

function formatTaskListOptions() {
  const taskListOptions = []

  try {
    const workflowData = $('Inicia pelo workflow dos dados de documentos')?.first()?.json
    // Extrai tarefas usando o método dinâmico para não quebrar independente da ordem do array
    const objTarefas = workflowData?.dados_documentos_fiscais?.find(item => item.tarefas)
    const tempTasksArray = objTarefas ? objTarefas.tarefas : []

    // Filtra pela chave ope001_codigo convertida para String para não ter problema de tipagem
    const tasksArray = payloadTarefas.status === "2" || payloadTarefas.status === "3" || payloadTarefas.status === "4" 
      ? tempTasksArray.filter(task => String(task.ope001_codigo) !== String(payloadTarefas.id_tarefa)) 
      : tempTasksArray

    if (!tasksArray || tasksArray.length === 0) {
      console.log("Nenhuma tarefa encontrada no caminho especificado")
    } else if (Array.isArray(tasksArray)) {
      taskListOptions.push(
        ...tasksArray.map((task, index) => ({
          id: index.toString(),  
          // Z-API limita titulo de listas a 24 caracteres
          title: (task?.endereco_logradouro || "Endereço não informado").substring(0, 24),
          description: `CTe: ${task?.cte001_codigo || "N/A"}`
        }))
      )
    } else {
      taskListOptions.push({
        id: "0", 
        title: (tasksArray?.endereco_logradouro || "Endereço não informado").substring(0, 24),
        description: `CTe: ${tasksArray?.cte001_codigo || "N/A"}`
      })
    }
  } catch (error) {
    console.log("Erro ao formatar lista de tarefas:", error.message)
  }

  return taskListOptions
}

// Função para mensagem única simples
const createWhatsAppMessage = (template, toNumber) => {
  const factory = new WhatsAppMessageFactory(toNumber)
  return factory.createMessage(template)
}

const taskListOptions = formatTaskListOptions();
const templateTarefas = {
  ...templates.SELECAO_TAREFAS,
  options: taskListOptions
}

let mensagens = []

// Manda a mensagem do próximo estado e depois já redefine ele para enviar junto o menu de tarefas
if (contexto.mensagens_consecutivas === "1" && contexto.proximo_estado) {
  mensagens.push(createWhatsAppMessage(templates[contexto.proximo_estado], contexto.id_whatsapp))
  contexto.proximo_estado = "SELECAO_TAREFAS"
}

if (contexto.proximo_estado === "SELECAO_TAREFAS") {
  mensagens.push(createWhatsAppMessage(templateTarefas, contexto.id_whatsapp))
} else {
  mensagens = createMessageFromContext(templates, contexto, currentTaskData)
}

let mensagensSaoArray = Array.isArray(mensagens)
if (!mensagensSaoArray) {
  mensagens = [mensagens]
}

mensagensSaoArray = Array.isArray(mensagens)
const quantasMensagens = mensagens.length

return {
  json: {
    resposta: mensagens,
    mensagens_sao_array: mensagensSaoArray,
