class WhatsAppMessageFactory {
  constructor(to) {
    this.to = to
  }

  createBaseMessage() {
    return {
      phone: this.to
    }
  }

  createListMessage(inputData) {
    const message = this.createBaseMessage()

    message.message = "Selecione do menu abaixo"
    message.optionList = {
      title: inputData?.header || "Opções disponíveis",
      buttonLabel: "Opções",
      options: (inputData?.options || []).map(option => ({
        id: option?.id?.toString() || "",
        title: option?.title || "",
        ...(option?.description && { description: option.description })
      }))
    }

    return message
  }

  createButtonMessage(inputData) {
    const message = this.createBaseMessage()

    // Se existir header, ele atua como a mensagem principal, senão usa um fallback
    message.message = inputData?.header || "Selecione das opções abaixo"
    message.buttonList = {
      buttons: (inputData?.options || []).map(option => ({
        id: option?.id?.toString() || "",
        label: option?.title || ""
      }))
    }

    return message
  }

  createTextMessage(inputData) {
    const message = this.createBaseMessage()
    message.message = inputData?.content || ""
    return message
  }

  createMessage(inputData) {
    if (!inputData || !inputData.type) {
      throw new Error(`Template inválido ou sem tipo: ${JSON.stringify(inputData)}`)
    }

    const messageTypes = {
      list: this.createListMessage,
      button: this.createButtonMessage,
      text: this.createTextMessage
    }

    const createFunction = messageTypes[inputData.type]
    if (!createFunction) {
      throw new Error(`Tipo de mensagem não suportado: ${inputData.type}`)
    }

    return createFunction.call(this, inputData)
  }
}

